                exhausted=(send_attempts>=%s),available_at={DB_NOW}+LEAST(60,POWER(2,LEAST(send_attempts-1,6)))
                WHERE event_id=%s AND publisher_token=%s AND publisher_until>{DB_NOW} RETURNING *''',
