    def _connection(self,*,write=False):
        with self.pool.connection() as db:
            with db.transaction():
                if not write:db.execute('SET TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY')
                yield db

    def close(self):self.pool.close()

