        self.assert_mode(db)
        if self.mode=='redis':db.execute(f'''INSERT INTO v3_index_outbox(event_id,task_id,generation,created_at,available_at)
            VALUES (%s,%s,%s,{DB_NOW},{DB_NOW})''',('wake-'+uuid4().hex,task_id,generation))

