            if db.execute('SELECT COUNT(*) AS n FROM v3_project_snapshots WHERE project_id=%s',(key,)).fetchone()['n']>=10:raise WorkspaceConflict('project_snapshot_quota_reached')
            snapshot='snapshot-'+uuid4().hex
